package txsaga

import (
	"context"
	"errors"
	"time"
)

// Publisher 由调用方实现，负责把一条 Outbox 事件发送到实际的下游
// （消息代理、HTTP 回调、其它进程内通道等）。本包不提供任何具体中间件适配。
//
// 实现应当满足至少一次投递语义：返回 error 时事件会被保留并可再次领取，
// 因此下游消费侧需要自身幂等。返回 nil 即视为投递成功，事件被标记已投递。
type Publisher interface {
	// Publish 发送单个事件。event.Payload 为结构化负载，可用 encoding/json 序列化。
	Publish(ctx context.Context, event Event) error
}

// PublisherFunc 让普通函数满足 Publisher 接口。
type PublisherFunc func(ctx context.Context, event Event) error

// Publish 实现 Publisher 接口。
func (f PublisherFunc) Publish(ctx context.Context, event Event) error { return f(ctx, event) }

// Relay 在 Store 与 Publisher 之间搬运 Outbox 事件：
// 领取待投递事件、交给 Publisher、成功 Ack、失败 Nack 后保留并允许重试。
// Relay 可被多个 worker 并发使用；零值不可用，请用 NewRelay 创建。
type Relay struct {
	store     Store
	publisher Publisher
	// batch 单次领取上限。
	batch int
	// retryBackoff 一批事件全部发送失败后的再次领取间隔。
	retryBackoff time.Duration
	// idleWait 没有待投递事件时的轮询等待。
	idleWait time.Duration
	// leaseTTL > 0 时启用带租约领取：worker 在 Publish/Ack/Nack 前退出，
	// 事件在租约到期后的下一轮自动恢复；0 表示沿用普通领取的默认行为。
	leaseTTL time.Duration
	// now 等时间依赖直接使用 time 包标准行为。
	sleep func(ctx context.Context, d time.Duration) error
}

// RelayOption 配置 Relay。
type RelayOption func(*Relay)

// WithBatch 设置单次领取事件数，默认 16。
func WithBatch(n int) RelayOption {
	return func(r *Relay) {
		if n > 0 {
			r.batch = n
		}
	}
}

// WithRetryBackoff 设置发送失败后的重试间隔，默认 200ms。
func WithRetryBackoff(d time.Duration) RelayOption {
	return func(r *Relay) {
		if d > 0 {
			r.retryBackoff = d
		}
	}
}

// WithIdleWait 设置无事件时的轮询间隔，默认 500ms。
func WithIdleWait(d time.Duration) RelayOption {
	return func(r *Relay) {
		if d > 0 {
			r.idleWait = d
		}
	}
}

// WithClaimLease 启用带租约领取并设置租约时长。
//
// 仅正时长生效；传入 0 或负时长不启用租约，Relay 沿用普通 ClaimPendingEvents
// 的默认行为。启用后，每次领取的事件在 ttl 内不会被再次领取；worker 在
// Publish、Ack 或 Nack 前退出时，事件于租约到期后的下一次 DeliverOnce/Run
// 自动恢复重投，从而保证至少一次投递。Store 必须实现 ClaimLeaseStore，
// 否则 DeliverOnce 返回 ErrClaimLeaseUnsupported（可 errors.Is）。
func WithClaimLease(ttl time.Duration) RelayOption {
	return func(r *Relay) {
		if ttl > 0 {
			r.leaseTTL = ttl
		}
	}
}

// NewRelay 创建事件投递器。
func NewRelay(store Store, publisher Publisher, opts ...RelayOption) *Relay {
	r := &Relay{
		store:        store,
		publisher:    publisher,
		batch:        16,
		retryBackoff: 200 * time.Millisecond,
		idleWait:     500 * time.Millisecond,
	}
	r.sleep = sleepWithContext
	for _, opt := range opts {
		opt(r)
	}
	return r
}

func sleepWithContext(ctx context.Context, d time.Duration) error {
	t := time.NewTimer(d)
	defer t.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-t.C:
		return nil
	}
}

// RelayResult 是单轮投递的结果统计。
type RelayResult struct {
	// Claimed 本轮领取的事件数。
	Claimed int
	// Delivered 发送成功并 Ack 的事件数。
	Delivered int
	// Failed 发送失败并 Nack 保留的事件数。
	Failed int
}

// DeliverOnce 执行一轮领取与投递，不阻塞等待。没有事件时立即返回空结果。
// 单个事件发送失败不影响同批其它事件；失败事件被 Nack，可在后续轮次继续领取。
//
// 通过 WithClaimLease 启用租约且 Store 未实现 ClaimLeaseStore 时，
// 返回包装了 ErrClaimLeaseUnsupported 的错误（可 errors.Is 判定）。
func (r *Relay) DeliverOnce(ctx context.Context) (RelayResult, error) {
	if r.leaseTTL > 0 {
		leased, ok := r.store.(ClaimLeaseStore)
		if !ok {
			return RelayResult{}, ErrClaimLeaseUnsupported
		}
		return r.deliverOnceLeased(ctx, leased)
	}
	return r.deliverOnce(ctx)
}

// deliverOnce 是未启用租约时的默认路径：领取即锁定，失败立即退回。
func (r *Relay) deliverOnce(ctx context.Context) (RelayResult, error) {
	events, err := r.store.ClaimPendingEvents(ctx, r.batch)
	if err != nil {
		return RelayResult{}, err
	}
	res := RelayResult{Claimed: len(events)}
	for _, ev := range events {
		if err := ctx.Err(); err != nil {
			// 退出前把尚未处理的已领取事件退回，避免它们滞留到进程重启。
			_ = r.store.NackEvent(ctx, ev.ID)
			res.Failed++
			continue
		}
		if err := r.publisher.Publish(ctx, *ev); err != nil {
			if nackErr := r.store.NackEvent(ctx, ev.ID); nackErr != nil {
				return res, nackErr
			}
			res.Failed++
			continue
		}
		if err := r.store.AckEvent(ctx, ev.ID); err != nil {
			return res, err
		}
		res.Delivered++
	}
	return res, nil
}

// deliverOnceLeased 是启用租约后的投递路径。
//
// 取消语义：
//   - 领取后、Publish 前 ctx 已取消：事件从未交给 Publish，按当前 ClaimID
//     立即 Nack，等不到租约到期；
//   - Publish 进行中取消：按 Publish 的返回结果处理，nil 走 Ack，error 走
//     Nack，不因 ctx 取消改变结论；
//   - worker 在任何一步退出（未 Nack）：租约到期后事件自动恢复重投。
//
// Ack/Nack 使用独立上下文，避免调用方 ctx 已取消导致确认/退回被 Store
// 拒绝而被迫等待租约到期。旧 ClaimID（租约已到期、事件被他人重新领取）
// 返回 ErrStaleClaim 时不作任何操作：当前事件与新租约由接管方负责。
func (r *Relay) deliverOnceLeased(ctx context.Context, store ClaimLeaseStore) (RelayResult, error) {
	claims, err := store.ClaimPendingEventsLeased(ctx, r.leaseTTL, r.batch)
	if err != nil {
		return RelayResult{}, err
	}
	res := RelayResult{Claimed: len(claims)}
	for _, c := range claims {
		if err := ctx.Err(); err != nil {
			if nackErr := store.NackLeasedEvent(context.Background(), c.Event.ID, c.ClaimID); nackErr != nil &&
				!errors.Is(nackErr, ErrStaleClaim) {
				return res, nackErr
			}
			res.Failed++
			continue
		}
		pubErr := r.publisher.Publish(ctx, *c.Event)
		if pubErr != nil {
			if nackErr := store.NackLeasedEvent(context.Background(), c.Event.ID, c.ClaimID); nackErr != nil &&
				!errors.Is(nackErr, ErrStaleClaim) {
				return res, nackErr
			}
			res.Failed++
			continue
		}
		if ackErr := store.AckLeasedEvent(context.Background(), c.Event.ID, c.ClaimID); ackErr != nil &&
			!errors.Is(ackErr, ErrStaleClaim) {
			return res, ackErr
		}
		res.Delivered++
	}
	return res, nil
}

// Run 循环执行投递，直到 ctx 被取消。至少一轮成功投递后返回 ctx.Err()。
// 全部事件发送失败的批次后按重试间隔等待；无事件时按空闲间隔等待。
func (r *Relay) Run(ctx context.Context) error {
	for {
		if err := ctx.Err(); err != nil {
			return err
		}
		res, err := r.DeliverOnce(ctx)
		if err != nil {
			return err
		}
		var wait time.Duration
		switch {
		case res.Claimed == 0:
			wait = r.idleWait
		case res.Failed > 0 && res.Delivered == 0:
			wait = r.retryBackoff
		default:
			wait = 0 // 本轮有成功投递，立即继续领取，尽快排空积压
		}
		if wait > 0 {
			if err := r.sleep(ctx, wait); err != nil {
				return err
			}
		}
	}
}

package txsaga

import (
	"context"
	"errors"
	"strings"
	"time"
)

// 事件历史查询相关的哨兵错误，调用方可用 errors.Is 判定。
var (
	// ErrEventHistoryUnsupported 当前 Store 未实现 EventHistoryStore。
	// 既有自定义 Store 无需新增任何方法即可继续使用，只是不支持历史查询。
	ErrEventHistoryUnsupported = errors.New("txsaga: store does not support event history")
	// ErrEventCursorNotFound 分页游标 AfterID 未命中：事件不存在，或不属于
	// 本次查询给定的执行身份。返回该错误时不返回任何记录，也不改变任何状态。
	ErrEventCursorNotFound = errors.New("txsaga: event cursor not found")
)

// defaultEventHistoryLimit 是单页上限非正数时采用的默认页大小。
const defaultEventHistoryLimit = 100

// EventHistoryQuery 是一次只读执行事件历史查询的输入。
//
// 执行身份由 Saga 名称、业务键与外部幂等键共同确定，与 Execute/GetResult
// 保持同一口径。事件严格按发生（追加）顺序分页，Ack、Nack、租约到期与
// 投递次数增加都不会改变顺序。
type EventHistoryQuery struct {
	// SagaName Saga 定义名称，必填；与执行记录的名称不符时返回 ErrExecutionNotFound。
	SagaName string
	// BusinessKey 业务键，必填。
	BusinessKey string
	// IdempotencyKey 外部幂等键，必填。
	IdempotencyKey string
	// AfterID 上一页最后一条事件 ID；为空表示从头查询。
	// 命中后从该事件的下一条开始返回；不属于本执行时返回 ErrEventCursorNotFound。
	AfterID string
	// Limit 单页事件数上限；非正数时按 100 条返回。
	Limit int
}

// EventRecord 是执行事件链中的一条只读审计记录。
//
// 身份、类型、发生时间与结构化负载在追加时确定；投递元数据
// （Deliveries/LastAttemptAt）反映查询当下的最新值。已 Ack 的事件同样
// 保留一份不可变身份字段、可继续审计的副本。记录为快照值，与存储内部
// 结构脱离，调用方修改不影响后续领取、投递与再次查询。
type EventRecord struct {
	// ID 事件唯一 ID，由存储在追加时分配，追加顺序单调。
	ID string
	// Type 事件类型，取值为 Event* 常量。
	Type string
	// OccurredAt 事件发生时间（状态提交时刻）。
	OccurredAt time.Time
	// Payload 结构化负载，即追加时的 EventPayload，可用 encoding/json 序列化。
	Payload any
	// BusinessKey 业务键。
	BusinessKey string
	// Deliveries 截至查询时该事件已进入领取/投递流程的次数（含首次）。
	// 发送失败退回后再次领取会增大；Ack 后保留最后一次计数。
	Deliveries int
	// LastAttemptAt 最近一次领取时间；从未被领取为零值。
	LastAttemptAt time.Time
}

// EventHistoryPage 是一页按追加顺序排列的执行事件。
type EventHistoryPage struct {
	// Events 本页事件，按事件发生及追加顺序升序排列。
	Events []EventRecord
	// NextAfterID 下一页查询应使用的游标：本页最后一条事件 ID。
	// 本页为空时与入参 AfterID 语义一致（从头查询则为空）。
	NextAfterID string
	// HasMore 游标之后是否还有事件。
	HasMore bool
}

// EventHistoryStore 是在 Store 之上可选实现的只读执行事件历史接口。
//
// 持久化 Store 通过实现本接口提供与 MemoryStore 一致的历史结果：
// 查询必须只读（不得推进执行、调用动作、追加事件或改变 Outbox 领取/投递
// 状态），并且每页只读取原子提交后可见的事件——一次 Commit 追加的多条
// 事件要么整体可见、要么整体不可见，跨页顺序始终等于追加顺序。
type EventHistoryStore interface {
	Store

	// ListEvents 按追加顺序返回一次执行的一页事件。
	//
	// 查询语义：
	//   - 执行不存在（或事件链为空但无执行记录）返回 ErrExecutionNotFound；
	//   - sagaName 与执行绑定的 Saga 名称不符返回 ErrExecutionNotFound；
	//   - afterID 非空且未命中（事件不存在或属于其它执行）返回 ErrEventCursorNotFound；
	//   - limit<=0 时按 100 条返回。
	//
	// 出错时不得返回部分结果，也不得改变任何状态与投递元数据。
	// 返回的记录须包含待投递、领取中、发送失败退回以及已 Ack 的全部事件，
	// 已 Ack 事件保留可审计副本。
	ListEvents(ctx context.Context, q EventHistoryQuery) (EventHistoryPage, error)
}

// ListEvents 按执行身份只读回看本次执行的完整事件链中的一页。
//
// 执行身份为 Saga 名称、业务键与外部幂等键，与 GetResult 同口径：
//   - 缺少 Saga 名称、业务键或外部幂等键：ErrInvalidDefinition；
//   - 执行不存在或 Saga 名称不匹配：ErrExecutionNotFound；
//   - AfterID 不属于该执行：ErrEventCursorNotFound；
//   - Store 未实现 EventHistoryStore：ErrEventHistoryUnsupported。
//
// 查询不推进执行、不调用动作、不追加事件，也不改变 Outbox 的领取、退回、
// 投递计数或 Ack 状态；事件顺序固定为追加顺序，分页通过
// EventHistoryPage.NextAfterID 继续，HasMore 报告游标之后是否还有事件。
func (e *Engine) ListEvents(ctx context.Context, q EventHistoryQuery) (EventHistoryPage, error) {
	if strings.TrimSpace(q.SagaName) == "" ||
		strings.TrimSpace(q.BusinessKey) == "" ||
		strings.TrimSpace(q.IdempotencyKey) == "" {
		return EventHistoryPage{}, ErrInvalidDefinition
	}
	if q.Limit <= 0 {
		q.Limit = defaultEventHistoryLimit
	}
	hs, ok := e.store.(EventHistoryStore)
	if !ok {
		return EventHistoryPage{}, ErrEventHistoryUnsupported
	}
	return hs.ListEvents(ctx, q)
}

// Package txsaga 提供可嵌入应用的 Saga 编排能力：带补偿的顺序步骤执行、
// 基于业务键与外部幂等键的执行身份去重，以及与状态原子共写的 Outbox 事件。
//
// 本包只依赖 Go 标准库，不规定任何磁盘文件格式；状态持久化由 Store 接口承载。
package txsaga

import (
	"context"
	"errors"
	"time"
)

// 终态状态：执行一旦进入以下任一状态即固定，后续同一执行身份的调用直接返回既有结果。
const (
	// StatusCompleted 所有正向步骤均已确认成功。
	StatusCompleted = "completed"
	// StatusFailed 某正向步骤失败，且此前确认成功步骤的补偿均已成功。
	StatusFailed = "failed"
	// StatusCompensationFailed 正向失败后，补偿过程中发生错误，结果固定在此状态。
	StatusCompensationFailed = "compensation_failed"
)

// 中间状态：执行尚未到达终态。
const (
	// StatusRunning 至少一个步骤已确认成功，仍有步骤待执行。
	StatusRunning = "running"
	// StatusCompensating 正向步骤已失败，正在逆序补偿此前确认成功的步骤。
	StatusCompensating = "compensating"
)

// 步骤处理结果。
const (
	// StepResultPending 步骤尚未被执行到（仅出现在 Result 中，持久状态以空串表示）。
	StepResultPending = "pending"
	// StepResultSucceeded 正向动作已确认成功。
	StepResultSucceeded = "succeeded"
	// StepResultFailed 正向动作返回错误（该步骤未确认成功，不会被补偿）。
	StepResultFailed = "failed"
	// StepResultCompensated 补偿动作已确认成功。
	StepResultCompensated = "compensated"
	// StepResultCompensationFailed 补偿动作返回错误（补偿步骤未确认，允许重试）。
	StepResultCompensationFailed = "compensation_failed"
)

// Outbox 事件类型，随状态变化追加。
const (
	// EventExecutionStarted 一次执行开始（首个步骤执行前）。
	EventExecutionStarted = "execution_started"
	// EventStepSucceeded 某正向步骤已提交成功状态。
	EventStepSucceeded = "step_succeeded"
	// EventStepFailed 某正向步骤失败，执行转入补偿。
	EventStepFailed = "step_failed"
	// EventStepCompensated 某步骤补偿已提交。
	EventStepCompensated = "step_compensated"
	// EventStepCompensationFailed 某步骤补偿失败。
	EventStepCompensationFailed = "step_compensation_failed"
	// EventExecutionCompleted 全部正向步骤完成，执行到达 completed 终态。
	EventExecutionCompleted = "execution_completed"
	// EventExecutionFailed 补偿全部完成，执行到达 failed 终态。
	EventExecutionFailed = "execution_failed"
	// EventCompensationFailed 补偿异常，执行到达 compensation_failed 终态。
	EventCompensationFailed = "compensation_failed"
)

// 哨兵错误，调用方可用 errors.Is 判定。
var (
	// ErrInvalidDefinition 定义非法（名称为空、步骤为空、步骤名为空、
	// 缺少正向动作、前置步骤未知/自依赖/重复/成环）或执行请求缺少外部幂等键。
	ErrInvalidDefinition = errors.New("txsaga: invalid saga definition")
	// ErrExecutionNotFound 未知执行身份：该业务键下不存在由给定 Saga 定义
	// 与外部幂等键标识的执行。
	ErrExecutionNotFound = errors.New("txsaga: execution not found")
	// ErrDefinitionConflict 相同业务键已绑定不同的 Saga 定义。
	// 同一业务键上的所有执行必须共用同一份定义。
	ErrDefinitionConflict = errors.New("txsaga: saga definition conflict for business key")
)

// ActionFunc 是一个步骤的正向幂等动作。
//
// 动作必须遵守幂等契约：同一步骤在进程崩溃、调用超时后可能被再次调用，
// 重复调用不得产生重复的业务效果。动作返回 nil 即视为该步骤确认成功，
// 之后引擎先提交成功状态，再执行下一步。返回由 Permanent 包装的错误
// 表示永久失败：重试立即结束，按预算耗尽的失败口径提交；普通错误按
// ActionRetry 预算重试。
type ActionFunc func(ctx context.Context, exec ExecutionView) error

// CompensationFunc 是已确认成功步骤的补偿幂等动作。
//
// 补偿按步骤成功顺序的相反方向逐个执行。补偿同样可能被重复调用，
// 实现必须自身幂等。返回 nil 表示补偿确认成功；返回错误时执行固定在
// compensation_failed 终态，未确认的补偿允许在后续调用中重试（终态结果不变）。
// 返回由 Permanent 包装的永久失败时立即结束补偿重试：即使 CompensateRetry
// 预算尚有剩余也只调用一次、不再等待，第一次确认失败即把该步记为
// compensation_failed 并把执行固定为 compensation_failed 终态。
type CompensationFunc func(ctx context.Context, exec ExecutionView) error

// RetryPolicy 配置一个动作的有限重试预算。
//
// 零值即默认语义：动作只调用一次（MaxAttempts 视为 1），失败后不等待。
// 每次动作返回非 nil 错误且仍有剩余次数时，引擎等待 RetryWait 后再次调用
// 同一动作；等待与动作本身都响应传入的 context。MaxAttempts 是包含首次
// 调用在内的最大总调用次数；负数次数或负等待时长属于非法定义。
//
// 动作返回由 Permanent 包装的永久失败时重试立即结束：即使 MaxAttempts
// 尚有剩余也只按实际调用次数计、不再等待，按与预算耗尽相同的口径提交该步
// 失败。普通错误仍按上述预算重试。
type RetryPolicy struct {
	// MaxAttempts 最大总调用次数（含首次）。零值按 1 处理；负数为非法定义。
	MaxAttempts int
	// RetryWait 每次失败后、再次调用前的等待时长。零值表示立即重试；
	// 负数为非法定义。
	RetryWait time.Duration
}

// Step 定义 Saga 中的一个正向步骤及其补偿。
type Step struct {
	// Name 步骤在 Saga 内唯一的名称。
	Name string
	// DependsOn 本步骤的前置步骤名称列表：全部前置步骤确认成功后本步骤
	// 才可启动。为空表示无前置，可与其它无前置步骤同时启动。
	// 一旦定义中任一步骤声明了前置，整个定义进入依赖图模式：调度只依据
	// 各步骤声明的前置关系，无前置的步骤并发执行；所有步骤都未声明前置时
	// 仍按 Steps 声明顺序逐个执行（顺序模式，公开行为与此前版本一致）。
	// 前置名称必须指向定义内已存在的其它步骤：未知前置、自依赖、重复前置
	// 或前置关系成环均属非法定义。
	DependsOn []string
	// Action 正向幂等动作，必填。
	Action ActionFunc
	// Compensate 反向补偿动作；无需补偿的步骤可留空，留空视为补偿成功。
	Compensate CompensationFunc
	// ActionRetry 正向动作的可选有限重试配置；零值表示只调用一次、失败即转补偿。
	ActionRetry RetryPolicy
	// CompensateRetry 补偿动作的可选有限重试配置；零值表示只调用一次、
	// 失败即固定为 compensation_failed。
	CompensateRetry RetryPolicy
}

// retryBudget 是归一化后的重试预算。
type retryBudget struct {
	maxAttempts int
	wait        time.Duration
}

func normalizeRetry(p RetryPolicy) retryBudget {
	n := p.MaxAttempts
	if n < 1 {
		n = 1
	}
	return retryBudget{maxAttempts: n, wait: p.RetryWait}
}

// Definition 是一个 Saga 的不可变定义。
type Definition struct {
	// Name Saga 定义名称；同时参与执行身份判定。
	Name string
	// Version 定义版本，参与定义指纹以区分同名但内容不同的定义。
	Version string
	// Steps Saga 的全部步骤，至少一个。未声明任何前置（DependsOn 均为空）时
	// 按声明顺序逐个执行；任一步骤声明前置后进入依赖图模式，按前置关系调度，
	// 无前置的步骤并发执行。Result.Steps 始终按本切片声明顺序返回。
	Steps []Step
}

// ExecutionRequest 发起一次 Saga 执行。
type ExecutionRequest struct {
	// BusinessKey 调用方的唯一业务键（如订单号），必填。
	BusinessKey string
	// IdempotencyKey 外部幂等键，必填；与业务键、Saga 定义共同确定执行身份。
	IdempotencyKey string
	// Payload 透传给动作的结构化业务输入，可为 nil。
	Payload any
}

// StepOutcome 是单个步骤在一次执行中的处理结果。
type StepOutcome struct {
	// Name 步骤名。
	Name string `json:"name"`
	// Result 取值为 StepResult* 常量。
	Result string `json:"result"`
	// Attempts 正向动作在本次确认阶段的实际调用次数（含预算内重试）；
	// 同身份重试已确认步骤时保持不变，大于 1 说明该步曾在预算内重试，
	// 或未确认步骤被同身份调用重新进入（动作须幂等）。
	Attempts int `json:"attempts"`
	// CompensationAttempts 补偿动作在本次确认阶段的实际调用次数（含预算内
	// 重试）；已确认补偿后保持不变。
	CompensationAttempts int `json:"compensation_attempts,omitempty"`
	// Error 最近一次失败原因；成功时为空。
	Error string `json:"error,omitempty"`
	// StartedAt 最近一次开始执行正向动作的时间，未执行过为零值。
	StartedAt time.Time `json:"started_at,omitempty"`
	// FinishedAt 最近一次正向动作返回的时间，未完成则为零值。
	FinishedAt time.Time `json:"finished_at,omitempty"`
}

// Result 是一次执行在某次调用后返回的确定状态快照。
type Result struct {
	// BusinessKey 业务键。
	BusinessKey string `json:"business_key"`
	// SagaName Saga 定义名称。
	SagaName string `json:"saga_name"`
	// IdempotencyKey 外部幂等键。
	IdempotencyKey string `json:"idempotency_key"`
	// Status 当前状态，取值为 Status* 常量；终态之一表示已确定。
	Status string `json:"status"`
	// FailureReason 正向失败原因；仅在 failed/compensation_failed 时非空。
	FailureReason string `json:"failure_reason,omitempty"`
	// CompensationError 最近一次补偿错误；仅 compensation_failed 时非空。
	CompensationError string `json:"compensation_error,omitempty"`
	// FailedStep 正向失败的步骤名；未失败为空。
	FailedStep string `json:"failed_step,omitempty"`
	// FailedCompensationStep 补偿失败的步骤名；未发生为空。
	FailedCompensationStep string `json:"failed_compensation_step,omitempty"`
	// Steps 各步骤处理结果，顺序与定义中的正向顺序一致。
	Steps []StepOutcome `json:"steps"`
	// Terminal 是否为固定终态。终态结果在后续调用中保持不变。
	Terminal bool `json:"terminal"`
}

// ExecutionView 是传给动作与补偿的执行只读视图。
type ExecutionView interface {
	// BusinessKey 返回本次执行的业务键。
	BusinessKey() string
	// SagaName 返回 Saga 定义名称。
	SagaName() string
	// IdempotencyKey 返回外部幂等键。
	IdempotencyKey() string
	// Payload 返回发起执行时透传的结构化负载。
	Payload() any
	// SucceededSteps 返回截至当前已确认成功的步骤名（按确认成功的先后
	// 顺序；顺序模式下与声明顺序一致）。
	SucceededSteps() []string
}

// Event 是随状态变化追加的 Outbox 事件。
type Event struct {
	// ID 事件唯一 ID，由存储在追加时分配。
	ID string
	// BusinessKey 业务键。
	BusinessKey string
	// Type 事件类型，取值为 Event* 常量。
	Type string
	// OccurredAt 事件发生时间（状态提交时刻）。
	OccurredAt time.Time
	// Payload 结构化负载，使用 encoding/json 可直接序列化。
	Payload any

	// 投递元数据，由 Claim/Ack/Nack 维护，不参与业务语义。
	deliveries    int
	lastAttemptAt time.Time
}

// Deliveries 返回该事件已进入领取/投递流程的次数（含首次）。
// 发送失败后保留事件并增加投递次数，调用方可据此判断是否重复投递。
func (e *Event) Deliveries() int { return e.deliveries }

// LastAttemptAt 返回最近一次领取时间；从未被领取为零值。
func (e *Event) LastAttemptAt() time.Time { return e.lastAttemptAt }

// EventPayload 是事件的结构化负载。
type EventPayload struct {
	SagaName       string `json:"saga_name"`
	IdempotencyKey string `json:"idempotency_key"`
	Step           string `json:"step,omitempty"`
	Status         string `json:"status,omitempty"`
	Reason         string `json:"reason,omitempty"`
	Attempt        int    `json:"attempt,omitempty"`
	// SucceededSteps 事件发生时已确认成功的步骤顺序快照。
	SucceededSteps []string `json:"succeeded_steps,omitempty"`
}

